def req(path,method="GET",data=None,token=None,expected=200):
    headers={"Content-Type":"application/json"}
    if token:headers["Authorization"]="Bearer "+token
    request=urllib.request.Request(base+path,method=method,headers=headers,data=None if data is None else json.dumps(data).encode())
    try:
        with urllib.request.urlopen(request,timeout=8) as r:status,body=r.status,r.read()
    except urllib.error.HTTPError as e:status,body=e.code,e.read()
    assert status==expected,"%s %s expected %s got %s body=%s"%(method,path,expected,status,body[:700])
    return json.loads(body) if body else {}
def check(name,fn):
    fn();passed.append(name);print("PASS",name)
def one(sql,p=()):
    with app.conn() as c:return c.execute(sql,p).fetchone()
def seed_business(user, name, plan):
    with app.conn() as c:
        cur=c.execute("INSERT INTO businesses(user_id,name,category,area,phone,email,description,plan,billing,status,payment_status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",(user["id"],name,"Plumbers","Johannesburg","+27123456789",user["email"],"Verified QA provider listing for growth-tier tests.",plan,"monthly","active","verified",app.now()))
        return int(cur.fetchone()["id"])
